n = 4   # board size n x n, and n queens

def safe(cols, col):
    row = len(cols)
    for r in range(row):              # same column or same diagonal?
        if cols[r] == col or abs(cols[r] - col) == row - r:
            return False
    return True

def place(cols, back):
    if len(cols) == n:
        return True
    for col in range(n):
        if safe(cols, col):
            cols.append(col)
            if place(cols, back):
                return True
            cols.pop()                # dead end: go back (backtrack)
            back[0] += 1
    return False

cols, back = [], [0]
if place(cols, back):
    for c in cols:
        print(". " * c + "Q " + ". " * (n - c - 1))
else:
    print("No solution for n =", n)
print("Backtracks:", back[0])
